/* Mock data for AI Training Platform Prototype */

/** 生成分布式训练 Pod 列表（演示滚动） */
function mockTrainingPods(jobName, count, nodeStart) {
  const pods = [];
  const base = nodeStart || 12;
  for (let i = 0; i < count; i++) {
    const isMaster = i === 0;
    const nodeIdx = base + Math.floor(i / 8); // 每节点 8 个 Pod（示意）
    pods.push({
      name: isMaster
        ? `${jobName}-master-0`
        : `${jobName}-worker-${String(i - 1).padStart(2, "0")}`,
      role: isMaster ? "Master" : "Worker",
      node: `gpu-node-${String(nodeIdx).padStart(3, "0")}`,
      status: "Running",
      restarts: i === 17 ? 1 : 0,
      gpu: `GPU${i % 8}`,
    });
  }
  return pods;
}

function mockFastxGpuUtilTag(row) {
  const parts = [
    `instance:${row.instance}`,
    "role:gpu",
    row.pci ? `pci_bus_id:${row.pci}` : null,
    `Hostname:${row.instance}`,
    "team:LOGIN",
    `DCGM_FI_DRIVER_VERSION:${row.driver}`,
    `gpu:${row.gpu}`,
    `modelName:${row.model}`,
    "partition:login",
    "__name__:DCGM_FI_DEV_GPU_UTIL",
    "model:A800",
    `UUID:${row.uuid}`,
    "job:gpu",
    `device:nvidia${row.gpu},`,
  ].filter(Boolean);
  return parts.join(",");
}

