function mockFastxWebhookPayload(opts) {
  return {
    originalBody: {
      faultName: opts.faultName ?? null,
      faultEnv: opts.faultEnv ?? null,
      cluster: opts.cluster ?? null,
      handlingStrategy: opts.handlingStrategy || "manual",
    },
    alarmInfo: {
      ruleId: opts.ruleId ?? null,
      alarmCount: opts.alarmCount ?? 1,
      level: opts.level ?? 2,
      name: opts.name,
      alarmData: opts.alarmData,
      firstAlarmTime: opts.firstAlarmTime,
      createUser: opts.createUser || "jialing.wu",
    },
  };
}

